const item = $input.first().json;
const body = item.body || item;

// Robust extraction from various wrapper shapes
const profile = body.prospect_profile || body.profile || null;
const research = body.research || null;
const analysis = body.venturelyhub_analysis || body.analysis || null;
const metadata = body.metadata || {};

const orgName = (profile?.organization_name || body.organization_name || '').trim();
const website = (profile?.website || body.website || '').trim();

let isValid = true;
let errorCode = '';
let errorMessage = '';

if (!orgName) {
  isValid = false;
  errorCode = 'MISSING_ORGANIZATION_NAME';
  errorMessage = 'Field organization_name is required and cannot be empty.';
} else if (!profile || typeof profile !== 'object') {
  isValid = false;
  errorCode = 'MISSING_PROSPECT_PROFILE';
  errorMessage = 'Phase 1 payload must contain a valid prospect_profile section.';
} else if (!analysis || typeof analysis !== 'object') {
  isValid = false;
  errorCode = 'MISSING_VENTURELYHUB_ANALYSIS';
  errorMessage = 'Phase 1 payload must contain a valid venturelyhub_analysis section.';
}

const isSynthetic = /example\.(com|org|net)/i.test(website) || 
                    /test|synthetic|mock|stealthco/i.test(orgName) || 
                    Boolean(metadata.test_fixture) || 
                    Boolean(body.test_fixture);

return [{
  json: {
    isValid,
    errorCode,
    errorMessage,
    raw_payload: body,
    organization_name: orgName,
    test_fixture: isSynthetic,
    source_execution_id: metadata.execution_id || body.execution_id || ''
  }
}];

const item = $input.first().json;
const body = item.raw_payload;

const profile = body.prospect_profile || {};
const research = body.research || {};
const analysis = body.venturelyhub_analysis || {};
const meta = body.metadata || {};

const normalized = {
  prospect_profile: {
    organization_name: profile.organization_name || item.organization_name || '',
    website: profile.website || '',
    type: profile.type || 'Not specified',
    location: profile.location || 'Not specified',
    description: profile.description || '',
    focus_areas: Array.isArray(profile.focus_areas) ? profile.focus_areas : [],
    industries: Array.isArray(profile.industries) ? profile.industries : [],
    programs: Array.isArray(profile.programs) ? profile.programs : [],
    technology_focus: Array.isArray(profile.technology_focus) ? profile.technology_focus : []
  },
  research: {
    relevant_activities: Array.isArray(research.relevant_activities) ? research.relevant_activities : [],
    partnership_signals: Array.isArray(research.partnership_signals) ? research.partnership_signals : [],
    relevant_contact_roles: Array.isArray(research.relevant_contact_roles) ? research.relevant_contact_roles : ['Decision Maker'],
    sources: Array.isArray(research.sources) ? research.sources : [],
    research_date: research.research_date || new Date().toISOString().split('T')[0]
  },
  venturelyhub_analysis: {
    fit_level: analysis.fit_level || 'MEDIUM',
    fit_reasons: Array.isArray(analysis.fit_reasons) ? analysis.fit_reasons : [String(analysis.fit_reasons || '')],
    venturelyhub_relevance: analysis.venturelyhub_relevance || '',
    relevant_services: Array.isArray(analysis.relevant_services) ? analysis.relevant_services : ['Product Engineering', 'AI Development'],
    recommended_offer: analysis.recommended_offer || 'Technology Partnership Discussion',
    value_proposition: analysis.value_proposition || '',
    outreach_angle: analysis.outreach_angle || analysis.personalization_angle || '',
    personalization_angle: analysis.personalization_angle || analysis.outreach_angle || '',
    recommended_contact_role: analysis.recommended_contact_role || (research.relevant_contact_roles && research.relevant_contact_roles[0]) || 'Decision Maker',
    recommended_cta: analysis.recommended_cta || analysis.suggested_cta || '15-minute introductory conversation',
    potential_objections: Array.isArray(analysis.potential_objections) ? analysis.potential_objections : [],
    confidence: analysis.confidence || 'MEDIUM'
  },
  source_execution_id: item.source_execution_id || meta.execution_id || '',
  test_fixture: item.test_fixture
};

return [{ json: normalized }];

const item = $input.first().json;
const p = item.prospect_profile;
const r = item.research;
const a = item.venturelyhub_analysis;

const prompt = `You are VenturelyHub's B2B Technology Personalization and Outbound Campaign Specialist.
Your task is to generate a complete, highly personalized multi-channel outbound campaign package based strictly on the verified Phase 1 prospect intelligence.

VENTURELYHUB COMPANY PROFILE & CORE CAPABILITIES:
VenturelyHub helps startups and enterprises build scalable digital products through technology, AI, and innovation:
- Product Engineering & Custom Software
- Web Development & Mobile App Development (iOS, Android, Flutter)
- SaaS Development & Enterprise Platforms
- AI Development, Custom AI Agents & Chatbots
- AI Analytics, Predictive BI & Data Intelligence
- Cloud Architecture, DevOps Automation, Server Management & CI/CD
- UI/UX Design, Design Systems & Product Strategy
- Custom SDK Development & API Integrations
- Startup Product Acceleration (MVP development, Tech clinics, Dedicated Engineering Pods)

VERIFIED PROSPECT INTELLIGENCE (Strictly Grounded):
${JSON.stringify(item, null, 2)}

STRICT OPERATIONAL & MESSAGING RULES:
1. Every factual statement must be grounded in the verified intelligence above.
2. NEVER invent funding, hiring, technology stacks, clients, revenues, milestones, or achievements not stated in the evidence.
3. If specific details are sparse, use cautious, general relevance ("Given your focus on...", "With your initiatives in...").
4. Tone: Concise, professional, human, helpful, consultative, zero hype, zero spam, zero fake urgency.
5. Do NOT mention all VenturelyHub services blindly; select only those directly relevant to the prospect.
6. Email sequence must include 4 distinct emails (Email 1, Follow-up 1, Follow-up 2, Follow-up 3), each with subject, body, and purpose.
7. LinkedIn sequence must include 3 touches (Connection note max 300 chars, Follow-up 1, Follow-up 2).
8. Meeting pitch must be a compact brief (Opening, Value Proposition, 2-4 Suggested Discussion Points, CTA).
9. Approval status must strictly be "PENDING_REVIEW".
10. Return valid JSON only adhering strictly to the requested schema.

SCHEMA SPECIFICATION:
{
  "personalization_analysis": {
    "why_this_prospect": "Specific commercial rationale connecting prospect focus to VenturelyHub",
    "relevant_signal": "The verified signal or activity from research supporting outreach",
    "personalization_angle": "The core thematic angle for personalization",
    "value_proposition": "Clear, compelling value proposition sentence",
    "recommended_offer": "${a.recommended_offer || 'Ecosystem Technology Partnership'}",
    "recommended_contact_role": "${a.recommended_contact_role || 'Decision Maker'}",
    "recommended_cta": "${a.recommended_cta || '15-minute alignment conversation'}",
    "tone": "Professional, collaborative, evidence-based",
    "claims_to_avoid": ["List of unsupported claims strictly avoided"],
    "risks": ["Potential outreach risks or context gaps"],
    "confidence": "${a.confidence || 'MEDIUM'}"
  },
  "email_sequence": {
    "email_1": { "subject": "String subject line", "body": "Concise 3-paragraph email body", "purpose": "Initial introduction and verified relevance" },
    "follow_up_1": { "subject": "String subject line", "body": "Short 2-paragraph follow-up reinforcing relevance", "purpose": "Reinforce relevance and offer specific support" },
    "follow_up_2": { "subject": "String subject line", "body": "Alternative angle or capability", "purpose": "Alternative angle or engineering capability" },
    "follow_up_3": { "subject": "String subject line", "body": "Polite close-the-loop message", "purpose": "Polite close-the-loop inquiry" }
  },
  "linkedin_sequence": {
    "connection_note": "Short natural note under 300 chars",
    "follow_up_1": { "message": "Short message referencing verified context", "purpose": "Reference verified context" },
    "follow_up_2": { "message": "Concise message introducing capability with soft CTA", "purpose": "Introduce VenturelyHub capability and soft CTA" }
  },
  "meeting_pitch": {
    "opening": "Why the conversation is relevant",
    "value_proposition": "What VenturelyHub can contribute",
    "suggested_discussion_points": ["Point 1", "Point 2", "Point 3"],
    "cta": "Reasonable next step"
  },
  "approval": {
    "approval_status": "PENDING_REVIEW",
    "review_notes": "Awaiting human review and channel dispatch selection."
  }
}`;

return [{
  json: {
    ...item,
    outbound_prompt: prompt
  }
}];

const item = $input.first().json;
const prepNode = $('PREPARE_OutboundPrompt').first().json;
const normNode = $('NORMALIZE_Phase1Output').first().json;

const profile = prepNode.prospect_profile || normNode.prospect_profile || {};
const research = prepNode.research || normNode.research || {};
const analysis = prepNode.venturelyhub_analysis || normNode.venturelyhub_analysis || {};
const isTestFixture = prepNode.test_fixture ?? normNode.test_fixture;

let rawText = '';
if (item.message?.content && typeof item.message.content === 'string') {
  rawText = item.message.content;
} else if (item.response && typeof item.response === 'string') {
  rawText = item.response;
} else if (item.content && typeof item.content === 'string') {
  rawText = item.content;
}

let parsed = null;
if (rawText && rawText.trim().length > 0) {
  try {
    parsed = JSON.parse(rawText.trim());
  } catch (e) {
    try {
      const cleaned = rawText.replace(/```json\n?|```/g, '').trim();
      parsed = JSON.parse(cleaned);
    } catch (e2) {
      try {
        const start = rawText.indexOf('{');
        const end = rawText.lastIndexOf('}');
        if (start !== -1 && end > start) {
          parsed = JSON.parse(rawText.slice(start, end + 1));
        }
      } catch (e3) {
        parsed = null;
      }
    }
  }
}

// Resilient deterministic fallback if Ollama times out or errors
if (!parsed || typeof parsed !== 'object' || !parsed.email_sequence) {
  const orgName = profile.organization_name || 'your team';
  const role = analysis.recommended_contact_role || 'Technology Leader';
  const offer = analysis.recommended_offer || 'Technology Capabilities Consultation';
  const valProp = analysis.value_proposition || `Supporting ${orgName} with scalable digital product engineering and AI capabilities.`;
  const angle = analysis.outreach_angle || `Exploring technology alignment for ${orgName}`;

  parsed = {
    personalization_analysis: {
      why_this_prospect: `Alignment between ${orgName} and VenturelyHub capabilities.`,
      relevant_signal: analysis.outreach_angle || 'Publicly verified organizational profile',
      personalization_angle: angle,
      value_proposition: valProp,
      recommended_offer: offer,
      recommended_contact_role: role,
      recommended_cta: analysis.recommended_cta || '15-minute introductory alignment discussion',
      tone: 'Professional, consultative, evidence-based',
      claims_to_avoid: ['Unverified funding status', 'Unverified tech stack details', 'Unverified hiring signals'],
      risks: ['Limited public evidence available for deep technical personalization'],
      confidence: analysis.confidence || 'LOW'
    },
    email_sequence: {
      email_1: {
        subject: `Exploring Technology Collaboration with ${orgName}`,
        body: `Hi [Name],\n\nI came across ${orgName} and noticed your focus on ${profile.focus_areas?.[0] || 'technology innovation'}.\n\nVenturelyHub is a software engineering partner helping organizations build scalable web, mobile, and AI solutions. ${valProp}\n\nWould you be open to a brief 15-minute conversation to explore whether our engineering capabilities align with your roadmap?\n\nBest regards,\nVenturelyHub Partnerships`,
        purpose: 'Initial introduction and verified relevance'
      },
      follow_up_1: {
        subject: `Re: Exploring Technology Collaboration with ${orgName}`,
        body: `Hi [Name],\n\nFollowing up briefly on my previous note. Given your initiatives around ${profile.focus_areas?.[0] || 'digital acceleration'}, we often help teams accelerate their delivery velocity with dedicated engineering pods.\n\nWould love to share a few relevant examples if helpful.\n\nBest,\nVenturelyHub Partnerships`,
        purpose: 'Reinforce relevance and offer specific support'
      },
      follow_up_2: {
        subject: `Engineering support for ${orgName}`,
        body: `Hi [Name],\n\nRecognizing that priorities evolve rapidly, wanted to share that VenturelyHub also provides architecture audits and AI enablement.\n\nIf this aligns with any upcoming priorities, happy to connect briefly.\n\nBest,\nVenturelyHub Partnerships`,
        purpose: 'Alternative angle or engineering capability'
      },
      follow_up_3: {
        subject: `Closing the loop - ${orgName} / VenturelyHub`,
        body: `Hi [Name],\n\nAssuming technology engineering support isn't top of mind right now. I'll pause our follow-ups here, but feel free to reach out if scalable software or AI development needs arise in the future.\n\nWishing you continued success.\n\nBest,\nVenturelyHub Partnerships`,
        purpose: 'Polite close-the-loop inquiry'
      }
    },
    linkedin_sequence: {
      connection_note: `Hi [Name], noticed your work at ${orgName} around ${profile.focus_areas?.[0] || 'technology'}. Would love to connect and follow your journey!`,
      follow_up_1: {
        message: `Thanks for connecting! Given your initiatives at ${orgName}, VenturelyHub works closely with organizations to build scalable digital products and AI systems.`,
        purpose: 'Reference verified context'
      },
      follow_up_2: {
        message: `Would you be open to a brief 15-minute chat sometime next week to exchange perspectives on technology execution?`,
        purpose: 'Introduce VenturelyHub capability and soft CTA'
      }
    },
    meeting_pitch: {
      opening: `Context of conversation around ${orgName}'s focus on ${profile.focus_areas?.[0] || 'technology'}.`,
      value_proposition: valProp,
      suggested_discussion_points: [
        `Overview of ${orgName}'s current digital product priorities`,
        'VenturelyHub dedicated engineering pod model',
        'Potential collaboration areas around AI or cloud architecture'
      ],
      cta: 'Agree on potential next exploratory step or technical review'
    },
    approval: {
      approval_status: 'PENDING_REVIEW',
      review_notes: 'Generated via resilient fallback due to LLM response format.'
    }
  };
}

return [{
  json: {
    phase1_data: prepNode,
    outbound_package: parsed,
    test_fixture: Boolean(isTestFixture)
  }
}];

const item = $input.first().json;
const pkg = item.outbound_package;
const p1 = item.phase1_data || {};
const profile = p1.prospect_profile || {};
const research = p1.research || {};

// Verify that forbidden hallucinations did not creep into emails or messages
const fullText = JSON.stringify(pkg).toLowerCase();

const flaggedTerms = [
  'series a', 'series b', 'seed round', 'raised $', 'venture funding',
  'noticed you are hiring', 'saw your job posting', 'congratulations on raising',
  'as seen on techcrunch', 'reduce costs by 40%', 'guaranteed 10x'
];

const violationsFound = [];
for (const term of flaggedTerms) {
  if (fullText.includes(term)) {
    // Check if this term was verified in research
    const verifiedSources = JSON.stringify(research).toLowerCase() + JSON.stringify(profile).toLowerCase();
    if (!verifiedSources.includes(term)) {
      violationsFound.push(term);
    }
  }
}

// Sanitize approval and add validation summary
const claimsValidation = {
  status: violationsFound.length === 0 ? 'VERIFIED' : 'SANITIZED',
  violations_detected: violationsFound,
  action_taken: violationsFound.length === 0 ? 'Passed strict claim grounding check' : 'Flagged for human reviewer inspection'
};

// Guarantee strict approval_status
pkg.approval = {
  approval_status: 'PENDING_REVIEW',
  review_notes: violationsFound.length === 0 
    ? 'All claims verified against Phase 1 evidence. Ready for human review.'
    : `Human review required: unverified claims flagged (${violationsFound.join(', ')}).`
};

return [{
  json: {
    ...item,
    claims_validation: claimsValidation
  }
}];

const item = $input.first().json;
const pkg = item.outbound_package;
const p1 = item.phase1_data || {};
const profile = p1.prospect_profile || {};
const analysis = p1.venturelyhub_analysis || {};
const claims = item.claims_validation || {};

const now = new Date();
const nowIso = now.toISOString();
const datePrefix = nowIso.split('T')[0].replace(/-/g, '');
const randomSuffix = Math.floor(1000 + Math.random() * 9000);
const executionId = `EXEC-P2-${datePrefix}-${randomSuffix}`;

const sourceExecId = p1.source_execution_id || p1.metadata?.execution_id || '';

// Clean, contract-compliant final structured JSON
const finalOutput = {
  personalization_analysis: pkg.personalization_analysis || {},
  email_sequence: pkg.email_sequence || {},
  linkedin_sequence: pkg.linkedin_sequence || {},
  meeting_pitch: pkg.meeting_pitch || {},
  approval: {
    approval_status: 'PENDING_REVIEW',
    review_notes: pkg.approval?.review_notes || 'Pending human review before any outreach action.'
  },
  claims_validation: claims,
  metadata: {
    execution_id: executionId,
    created_at: nowIso,
    workflow_name: 'VenturelyHub Outbound Generation',
    phase: 'Phase 2 - Personalization & Outbound Generation',
    test_fixture: Boolean(item.test_fixture),
    source_execution_id: sourceExecId
  }
};

// Prepare flattened row for Google Sheets Outbound Generation Outputs
const email1 = pkg.email_sequence?.email_1 || {};
const sheetRow = {
  execution_id: executionId,
  created_at: nowIso,
  workflow_name: 'VenturelyHub Outbound Generation',
  phase: 'Phase 2 - Outbound Generation',
  status: 'SUCCESS',
  test_fixture: Boolean(item.test_fixture),
  organization_name: profile.organization_name || 'Unknown',
  target_channel: 'Email + LinkedIn',
  subject_line: email1.subject || 'Exploring Technology Collaboration',
  message_body: email1.body || '',
  personalization_angle: pkg.personalization_analysis?.personalization_angle || analysis.outreach_angle || '',
  raw_output_json: JSON.stringify(finalOutput)
};

return [{
  json: {
    ...sheetRow,
    _final_response: finalOutput
  }
}];

const item = $input.first().json;
const original = item._final_response || $('BUILD_OutputPayload').first().json._final_response;
return [{ json: original }];

const item = $input.first().json;
const now = new Date();
const nowIso = now.toISOString();
const datePrefix = nowIso.split('T')[0].replace(/-/g, '');
const randomSuffix = Math.floor(1000 + Math.random() * 9000);
const eventId = `EVT-P2-${datePrefix}-${randomSuffix}`;

const errorResponse = {
  error: {
    code: item.errorCode || 'INVALID_INPUT',
    message: item.errorMessage || 'Invalid payload provided to Outbound Generation workflow.'
  },
  approval: {
    approval_status: 'PENDING_REVIEW',
    review_notes: 'Execution rejected during input validation.'
  },
  metadata: {
    event_id: eventId,
    created_at: nowIso,
    workflow_name: 'VenturelyHub Outbound Generation',
    phase: 'Phase 2 - Personalization & Outbound Generation',
    status: 'VALIDATION_FAILED',
    test_fixture: Boolean(item.test_fixture)
  }
};

const systemEventRow = {
  event_id: eventId,
  created_at: nowIso,
  workflow_name: 'VenturelyHub Outbound Generation',
  phase: 'Phase 2 - Outbound Generation',
  event_type: item.errorCode || 'VALIDATION_FAILURE',
  status: 'VALIDATION_FAILED',
  test_fixture: Boolean(item.test_fixture),
  message: item.errorMessage || 'Input validation failed.',
  raw_event_json: JSON.stringify(errorResponse)
};

return [{
  json: {
    ...systemEventRow,
    _error_response: errorResponse
  }
}];

const item = $input.first().json;
const original = item._error_response || $('FORMAT_ErrorOutput').first().json._error_response;
return [{ json: original }];
